import React from 'react';

export default function EventCard({ event, onClick, isSelected }) {
  return (
    <div
      onClick={() => onClick && onClick(event)}
      style={{
        background: 'var(--surface)',
        border: `1px solid ${isSelected ? 'var(--text-primary)' : 'var(--border)'}`,
        borderRadius: 'var(--radius-lg)',
        padding: '16px',
        cursor: onClick ? 'pointer' : 'default',
        transition: 'border-color 0.15s',
      }}
      onMouseEnter={e => { if (!isSelected) e.currentTarget.style.borderColor = 'var(--border-hover)'; }}
      onMouseLeave={e => { if (!isSelected) e.currentTarget.style.borderColor = 'var(--border)'; }}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 6 }}>
        <h3 style={{
          fontFamily: 'var(--font-title)',
          fontWeight: 800,
          fontStyle: 'italic',
          fontSize: 22,
          color: 'var(--text-primary)',
          lineHeight: 1.1,
        }}>
          {event.name}
        </h3>
        <span style={{
          fontFamily: 'var(--font-body)',
          fontSize: 11,
          fontWeight: 500,
          padding: '2px 8px',
          background: 'var(--accent-light)',
          color: 'var(--accent-text)',
          borderRadius: 99,
          whiteSpace: 'nowrap',
          marginLeft: 8,
        }}>
          {event.tags[0]}
        </span>
      </div>

      <div style={{ fontFamily: 'var(--font-body)', fontSize: 12, color: 'var(--text-muted)', marginBottom: 8 }}>
        📍 {event.city} · {event.country}
      </div>

      <div style={{ display: 'flex', gap: 16, fontFamily: 'var(--font-body)', fontSize: 12, color: 'var(--text-secondary)', marginBottom: 10 }}>
        <span>📅 {event.date}</span>
        <span>🕐 {event.time}</span>
      </div>

      <p style={{ fontFamily: 'var(--font-body)', fontSize: 13, fontWeight: 300, color: 'var(--text-secondary)', lineHeight: 1.7, marginBottom: 12 }}>
        {event.description}
      </p>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
        {event.tags.map(tag => (
          <span key={tag} style={{
            fontFamily: 'var(--font-body)',
            fontSize: 11,
            padding: '2px 8px',
            borderRadius: 99,
            border: '1px solid var(--border)',
            color: 'var(--text-muted)',
          }}>
            {tag}
          </span>
        ))}
      </div>
    </div>
  );
}
